//--- is itself an object/array is captured whole rather than cut off
//--- at its first internal comma. This is a targeted extractor (not
//--- a general parser) because the manifest has a small, fixed key
//--- set -- a full recursive-descent grammar would be more code for
//--- no practical benefit here.
string
needle =
"\"
" + key + "
\
":"
;
int
pos =
StringFind
(json, needle);
if
(pos <
0
)
return
(
""
);
