cursor = pos +
StringLen
(needle);
int
len =
StringLen
(json);
//--- skip whitespace between the colon and the value proper.
while
(cursor < len &&
StringGetCharacter
(json, cursor) ==
' '
)
      cursor++;
ushort
first =
StringGetCharacter
(json, cursor);
int
start = cursor;
if
(first ==
'['
|| first ==
'{'
)
     {
//--- bracketed value: walk forward counting depth until the
