ushort
open_ch  = first;
ushort
close_ch = (first ==
'['
) ?
']'
:
'}'
;
int
depth =
0
;
for
(
int
i = cursor; i < len; i++)
        {
ushort
c =
StringGetCharacter
(json, i);
if
(c == open_ch)
            depth++;
else
if
(c == close_ch)
           {
