if
(depth ==
0
)
return
(
StringSubstr
(json, start, i - start +
1
));
           }
        }
return
(
StringSubstr
(json, start, len - start));
     }
else
if
(first ==
'"'
)
     {
//--- quoted string value: find the closing quote.
int
i = cursor +
1
;
while
(i < len &&
StringGetCharacter
(json, i) !=
'"'
)
         i++;
return
(
StringSubstr
(json, start, i - start +
1
));
     }
else
{
//--- bare number/literal: ends at the next comma or closing
//--- brace at the current (top) level.
int
i = cursor;
while
(i < len)
        {
ushort
c =
StringGetCharacter
(json, i);
if
(c ==
','
